window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[308]={"id":"308","numero":308,"titre":"Tumeurs du pancréas","objectifs":[{"id":"308-1","rang":"A","rubrique":"Définition","titre":"Connaître les deux principaux types histologiques des tumeurs du pancréas","contenu":"<p><strong>Tumeurs du pancréas</strong> regroupent des entités <span class=\"kw-def\">bénignes</span> ou <span class=\"kw-alerte\">malignes</span>, <span class=\"kw-def\">solides</span> ou <span class=\"kw-def\">kystiques</span>, développées à partir du tissu <span class=\"kw-def\">exocrine</span> (acineux + canalaire) ou <span class=\"kw-def\">endocrine</span> (îlots de Langerhans).</p>\n\n      <p><strong>Deux grands types histologiques de cancers</strong> définissent l'item :</p>\n      <ul>\n        <li><span class=\"kw-def\">Adénocarcinome canalaire (ductal)</span> du pancréas exocrine — <span class=\"kw-chiffre\">95 %</span> des cancers du pancréas, dont <span class=\"kw-chiffre\">90 %</span> sont des adénocarcinomes canalaires purs.</li>\n        <li><span class=\"kw-def\">Tumeurs neuroendocrines malignes (TNE)</span> — <span class=\"kw-chiffre\">2-4 %</span>, non sécrétantes (cas le plus fréquent) ou sécrétantes (<span class=\"kw-ttt\">insuline</span>, gastrine, VIP, <span class=\"kw-ttt\">glucagon</span>, somatostatine…).</li>\n      </ul>\n      <p>Autres types histologiques plus rares : <span class=\"kw-clinique\">carcinome</span> à cellules acineuses, adénosquameux.</p>\n\n      <h4><span class=\"kw-def\">Classification</span> générale des tumeurs du pancréas</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Malignes</th><th>Bénignes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Solides</span> (<span class=\"kw-chiffre\">80 %</span>)</th>\n            <td>\n              <strong>Adénocarcinome ++</strong> <br>\n              <span class=\"kw-def\">Tumeur neuroendocrine</span> maligne <br>\n              Tumeurs rares (acineuses, adénosquameux)\n            </td>\n            <td>\n              <span class=\"kw-def\">TNE</span> bénignes <br>\n              Tumeurs rares\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Kystiques</span> (<span class=\"kw-chiffre\">20 %</span>)</th>\n            <td>\n              <span class=\"kw-def\">TIPMP</span> ++ <br>\n              <span class=\"kw-def\">Cystadénocarcinome mucineux</span> <br>\n              <span class=\"kw-def\">Tumeur pseudo-papillaire et solide</span> (de Frantz)\n            </td>\n            <td>\n              <span class=\"kw-def\">TIPMP</span> ++ <br>\n              <span class=\"kw-def\">Cystadénome mucineux</span> <br>\n              <span class=\"kw-def\">Cystadénome séreux</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Repère sémantique</strong> — <span class=\"kw-def\">TIPMP</span> = <em>tumeur intra-canalaire papillaire et mucineuse du pancréas</em>. Présente dans <span class=\"kw-clinique\">les</span> colonnes <strong>maligne</strong> ET <strong>bénigne</strong> car son risque dégénératif dépend du canal atteint (principal &gt; secondaire).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 293 — Anapath · 294 — Traitement des cancers</em></p>","frequence":0},{"id":"308-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie et les facteurs de risque de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","contenu":"<h4>Adénocarcinome du pancréas — <span class=\"kw-def\">épidémiologie</span></h4>\n      <ul>\n        <li><strong>France 2018</strong> : <span class=\"kw-chiffre\">14 000</span> nouveaux cas/an, <span class=\"kw-chiffre\">11 500</span> décès/an.</li>\n        <li><strong>6ᵉ cancer</strong> le plus fréquent, <span class=\"kw-alerte\">3ᵉ cause de mortalité par cancer en Europe</span>, sera la <span class=\"kw-alerte\">2ᵈᵉ aux USA d'ici 2030</span>.</li>\n        <li><strong><span class=\"kw-def\">Incidence</span> en forte augmentation</strong> (doublement en &gt;<span class=\"kw-chiffre\"> 10 ans</span>), âge médian au diagnostic <span class=\"kw-chiffre\">71 ans</span> (pic <span class=\"kw-chiffre\">60-70 ans</span>), sex-ratio <span class=\"kw-chiffre\">1,4 H/F</span>.</li>\n        <li><span class=\"kw-alerte\">Mauvais pronostic</span> — survie à<span class=\"kw-chiffre\"> 5 ans</span> <span class=\"kw-chiffre\">5-10 %</span> : <span class=\"kw-clinique\">symptômes tardifs</span>, localisation profonde, <span class=\"kw-alerte\">potentiel métastatique précoce</span>, absence de <span class=\"kw-def\">dépistage</span>.</li>\n      </ul>\n\n      <h4>Tumeurs neuroendocrines (TNE) du pancréas — <span class=\"kw-def\">épidémiologie</span></h4>\n      <ul>\n        <li>Tumeurs <span class=\"kw-def\">rares</span> — <span class=\"kw-chiffre\">2-4 %</span> des tumeurs du pancréas, <span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">1,2 / 100 000</span> habitants en augmentation.</li>\n        <li>Âge plus jeune que l'adénocarcinome : <span class=\"kw-chiffre\">30-60 ans</span>.</li>\n        <li><span class=\"kw-def\">Non fonctionnelles</span> dans <span class=\"kw-chiffre\">75 %</span> des cas, fonctionnelles dans <span class=\"kw-chiffre\">25 %</span>.</li>\n        <li><span class=\"kw-alerte\">Malignité dans &gt; 60 %</span> des TNE, sauf <span class=\"kw-def\">insulinome</span> (risque métastatique <span class=\"kw-chiffre\">&lt; 10 %</span>).</li>\n        <li><span class=\"kw-def\">Pronostic</span> dépend de la <strong><span class=\"kw-bio\">différenciation</span></strong>, de l'index mitotique et du <span class=\"kw-bio\">Ki-67</span> (cf. obj-3).</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> — adénocarcinome</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs de risque</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Âge</th>\n            <td><span class=\"kw-def\">Incidence</span> augmente avec l'âge (déclin après <span class=\"kw-chiffre\">85 ans</span>, probable sous-diagnostic).</td>\n          </tr>\n          <tr>\n            <th>Mode de vie</th>\n            <td>\n              <strong><span class=\"kw-etio\">Tabagisme</span></strong> : <span class=\"kw-etio\">1ʳᵉ cause identifiée</span>, explique <span class=\"kw-chiffre\">20 %</span> des cas, RR <span class=\"kw-chiffre\">1,75</span> ; <br>\n              <strong><span class=\"kw-etio\">Obésité</span></strong> : <span class=\"kw-etio\">BMI &gt; 30 kg/m²</span> RR <span class=\"kw-chiffre\">1,72</span> ; <br>\n              <strong><span class=\"kw-etio\">Alcool</span></strong> : via la <span class=\"kw-etio\">pancréatite chronique</span> et l'obésité.\n            </td>\n          </tr>\n          <tr>\n            <th>Pathologies</th>\n            <td>\n              <strong><span class=\"kw-clinique\">Pancréatite chronique</span></strong> : RR <span class=\"kw-chiffre\">14,4</span>, <span class=\"kw-chiffre\">5 %</span> à<span class=\"kw-chiffre\"> 20 ans</span> (alcoolique), <span class=\"kw-chiffre\">40 %</span> à<span class=\"kw-chiffre\"> 50 ans</span> si <span class=\"kw-etio\">PRSS1</span> <span class=\"kw-etio\">héréditaire</span> ; <br>\n              <strong><span class=\"kw-etio\">Diabète</span></strong> : <span class=\"kw-etio\">DT2 ancien</span> RR <span class=\"kw-chiffre\">1,12</span> ; <br>\n              <strong>DT1</strong> n'est <span class=\"kw-ci\">pas un FdR</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>ATCD familial</th>\n            <td>\n              Risque <span class=\"kw-chiffre\">×3,2</span> si 1 parent au 1ᵉʳ degré ; <br>\n              Risque <span class=\"kw-chiffre\">×32</span> si 2 apparentés au 1ᵉʳ degré ; <br>\n              Critères du cancer pancréatique familial : <span class=\"kw-chiffre\">2</span> apparentés dont <span class=\"kw-chiffre\">≥ 1</span> au 1ᵉʳ degré, ou <span class=\"kw-chiffre\">3</span> apparentés tous degrés.\n            </td>\n          </tr>\n          <tr>\n            <th>Prédisposition <span class=\"kw-etio\">génétique</span> (<span class=\"kw-chiffre\">~10 %</span>)</th>\n            <td>\n              <span class=\"kw-etio\">BRCA2</span> (plus rarement BRCA1) ; <br>\n              <span class=\"kw-etio\">Syndrome de Lynch</span> (mésappariement ADN) ; <br>\n              <span class=\"kw-etio\">CDKN2a</span> (<span class=\"kw-clinique\">mélanome</span> familial FAMMM) ; <br>\n              <span class=\"kw-etio\">STK11</span> (<span class=\"kw-clinique\">syndrome de Peutz</span>-Jeghers) ; <br>\n              <span class=\"kw-etio\">PRSS1 / SPINK1</span> (pancréatites héréditaires) ; <br>\n              Ataxie-télangiectasie.\n            </td>\n          </tr>\n          <tr>\n            <th>Lésions précancéreuses</th>\n            <td>\n              <span class=\"kw-def\">TIPMP</span> (tumeurs intra-canalaires papillaires et mucineuses) ; <br>\n              <span class=\"kw-def\">Cystadénome mucineux</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> — TNE</h4>\n      <ul>\n        <li>Formes <strong>sporadiques</strong> dans <span class=\"kw-chiffre\">80-90 %</span> ; formes familiales dans <span class=\"kw-chiffre\">10-20 %</span>.</li>\n        <li><span class=\"kw-etio\">NEM1</span> (néoplasie endocrinienne multiple type 1) — <strong>+++</strong>.</li>\n        <li><span class=\"kw-etio\">Maladie de Von Hippel-Lindau (VHL)</span> — plus rarement.</li>\n        <li><span class=\"kw-etio\">Sclérose tubéreuse de Bourneville</span>.</li>\n        <li><span class=\"kw-etio\">Neurofibromatose de type 1</span> (maladie de von Recklinghausen).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique majeur</strong> — un <span class=\"kw-clinique\">diabète récent (&lt; 2 ans)</span> chez un sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> sans FdR métabolique <strong>n'est pas un facteur causal</strong> mais un <span class=\"kw-alerte\">signe révélateur</span> (<span class=\"kw-etio\">paranéoplasique</span>) d'un cancer du pancréas. Idem pour des <span class=\"kw-clinique\">phlébites migratrices récidivantes</span> ou une <span class=\"kw-clinique\">embolie pulmonaire inexpliquée</span> &gt;<span class=\"kw-chiffre\"> 50 ans</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 290 — Epidémiologie cancers</em></p>","frequence":1},{"id":"308-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif HOT</strong> — <span class=\"kw-chiffre\">6⭐</span> brutes (cappées à 5) : objectif le plus tombé aux QCM EDN sur l'item 308. À maîtriser par cœur.\n      </div>\n\n      <h4>1 · Adénocarcinome du pancréas — présentation clinique</h4>\n      <p>Diagnostic le plus souvent <span class=\"kw-alerte\">tardif</span>, la sémiologie varie selon le siège <span class=\"kw-etio\">tumoral</span> (<span class=\"kw-chiffre\">60-70 %</span> tête, <span class=\"kw-chiffre\">20 %</span> corps, <span class=\"kw-chiffre\">10 %</span> queue).</p>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Signes cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-clinique\">AEG</span> ⭐</th>\n            <td>\n              <span class=\"kw-clinique\">Anorexie</span> ; <span class=\"kw-clinique\">fatigue</span> ; <span class=\"kw-clinique\">amaigrissement</span> souvent rapide et important ; <br>\n              Origine multifactorielle : douleurs, <span class=\"kw-clinique\">ictère</span>, cytokines, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-clinique\">stéatorrhée</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>Douleur ⭐</th>\n            <td>\n              Signe révélateur le plus fréquent (<span class=\"kw-chiffre\">70-75 %</span>), surtout si tumeur du <span class=\"kw-def\">corps</span> ; <br>\n              <span class=\"kw-clinique\">Douleur solaire transfixiante insomniante</span> favorisée par le décubitus dorsal ; <br>\n              Témoigne d'un <span class=\"kw-alerte\">envahissement des plexus cœliaques</span> (ancien plexus solaire) ; <br>\n              Peut se projeter sous <span class=\"kw-clinique\">les</span> côtes ou uniquement dans le <span class=\"kw-clinique\">dos</span> (consultation initiale chez le rhumatologue).\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Ictère</span> (tumeur de la tête)</th>\n            <td>\n              <span class=\"kw-clinique\">Ictère nu cholestatique</span> dans <span class=\"kw-chiffre\">50 %</span> des cas, lentement progressif sans <span class=\"kw-clinique\">rémission</span> ; <br>\n              <strong>Nu</strong> = sans <span class=\"kw-clinique\">fièvre</span> ni <span class=\"kw-clinique\">colique hépatique</span> → DD lithiase biliaire ; <br>\n              <span class=\"kw-clinique\">Urines foncées</span> + <span class=\"kw-clinique\">selles décolorées</span> + <span class=\"kw-clinique\">prurit</span> avec lésions de grattage ; <br>\n              <span class=\"kw-def\">Loi de Courvoisier-Terrier</span> : grosse <span class=\"kw-clinique\">vésicule</span> tendue indolore palpable <span class=\"kw-chiffre\">1×/2</span> dans <span class=\"kw-clinique\">les</span> cancers de la tête ; <br>\n              <span class=\"kw-alerte\">Risque d'angiocholite</span> ⚠️ (fièvre, frissons, <span class=\"kw-alerte\">sepsis</span>).\n            </td>\n          </tr>\n          <tr>\n            <th>Autres symptômes</th>\n            <td>\n              <span class=\"kw-clinique\">Pancréatite aiguë</span> révélatrice (<span class=\"kw-chiffre\">1-5 %</span>) ; <br>\n              <span class=\"kw-clinique\">Vomissements</span> par sténose duodénale ; <br>\n              <span class=\"kw-clinique\">Diarrhée</span> ± <span class=\"kw-clinique\">stéatorrhée</span> ; <br>\n              <span class=\"kw-clinique\">Occlusion</span> ou <span class=\"kw-clinique\">syndrome de Koenig</span> sur carcinose ; <br>\n              Métastases hépatiques / péritonéales / pulmonaires révélatrices.\n            </td>\n          </tr>\n          <tr>\n            <th>Palpation</th>\n            <td>\n              <span class=\"kw-clinique\">Hépatomégalie</span> : bord lisse (<span class=\"kw-clinique\">cholestase</span>) ou dure et nodulaire (métastases) ; <br>\n              <span class=\"kw-clinique\">Masse</span> pancréatique parfois palpable ; <br>\n              <span class=\"kw-clinique\">Ascite</span>, métastases péritonéales palpables (Douglas, ombilic) ; <br>\n              <span class=\"kw-def\">Adénopathie de Troisier</span> (sus-claviculaire gauche).\n            </td>\n          </tr>\n          <tr>\n            <th>Signes paranéoplasiques généraux ⭐</th>\n            <td>\n              <strong><span class=\"kw-alerte\">Décompensation</span></strong> d'un <span class=\"kw-etio\">diabète</span> connu, ou survenue d'un <span class=\"kw-clinique\">diabète récent</span> chez un sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> sans FdR ⭐ ; <br>\n              <span class=\"kw-clinique\">Phlébites migratrices et récidivantes</span> + embolies pulmonaires → justifient la recherche d'un cancer &gt;<span class=\"kw-chiffre\"> 50 ans</span> ; <br>\n              Syndrome dépressif ou anxiété fréquents (prise en charge adaptée).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Tumeurs neuroendocrines (TNE) — présentation clinique</h4>\n      <p>Diagnostic souvent tardif : symptômes peu spécifiques (<span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">douleur abdominale</span>, <span class=\"kw-clinique\">ictère</span>), <span class=\"kw-alerte\">découverte fortuite</span> fréquente (incidentalome), ou à l'occasion du bilan d'une forme familiale (<span class=\"kw-etio\">NEM1</span>, <span class=\"kw-etio\">VHL</span>).</p>\n\n      <ul>\n        <li><span class=\"kw-def\">TNE non fonctionnelles</span> (<span class=\"kw-chiffre\">75-80 %</span>) — absence de symptômes liés à la sécrétion <span class=\"kw-etio\">tumorale</span>, même si la tumeur sécrète.</li>\n        <li><span class=\"kw-def\">TNE fonctionnelles</span> (<span class=\"kw-chiffre\">20-25 %</span>) — symptômes liés à une hypersécrétion hormonale.</li>\n      </ul>\n\n      <h4>Principales TNE fonctionnelles du pancréas</h4>\n      <table >\n        <thead>\n          <tr><th>Tumeur</th><th><span class=\"kw-def\">Incidence</span></th><th>Présentation clinique</th><th>Sécrétion / Marqueur</th><th>Malignité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Insulinome</span></th>\n            <td><span class=\"kw-chiffre\">70-80 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Hypoglycémie organique</span> chez sujet <span class=\"kw-chiffre\">30-50 ans</span>, au jeûne ou à l'effort ; <br>\n              Symptômes <strong>adrénergiques</strong> : <span class=\"kw-clinique\">sueurs</span>, tremblements, <span class=\"kw-clinique\">tachycardie</span> ; <br>\n              Signes <strong>neuroglucopéniques</strong> : désorientation, crises comitiales, <span class=\"kw-alerte\">coma</span> ; <br>\n              <span class=\"kw-clinique\">Prise de poids</span> dans <span class=\"kw-chiffre\">30 %</span> des cas.\n            </td>\n            <td>\n              <span class=\"kw-bio\">Insuline inadaptée à la glycémie basse</span> + <span class=\"kw-bio\">peptide C</span> + <span class=\"kw-bio\">proinsuline</span>.\n            </td>\n            <td><span class=\"kw-chiffre\">&lt; 10 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Gastrinome</span> <br>(<span class=\"kw-def\">syndrome de Zollinger-Ellison</span>)</th>\n            <td><span class=\"kw-chiffre\">20-25 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Maladie ulcéreuse sévère</span> : ulcères <strong>multiples ou récidivants</strong> souvent compliqués (hémorragie, perforation), souvent associés à une <span class=\"kw-clinique\">œsophagite peptique sévère</span> ; <br>\n              <span class=\"kw-clinique\">Diarrhée chronique volumogénique</span> sécrétoire avec malabsorption ; <br>\n              <strong>Améliorée ou disparaît sous <span class=\"kw-ttt\">IPP</span></strong> ; <br>\n              Sporadique <span class=\"kw-chiffre\">75 %</span>, ou associée à <span class=\"kw-etio\">NEM1</span>.\n            </td>\n            <td>\n              <span class=\"kw-bio\">Gastrine</span> élevée + débit acide basal élevé.\n            </td>\n            <td><span class=\"kw-chiffre\">50-60 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">VIPome</span> <br>(<span class=\"kw-def\">syndrome de Verner-Morrison</span>)</th>\n            <td><span class=\"kw-chiffre\">4 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Diarrhée hydroélectrolytique aqueuse profuse</span> ; <br>\n              <span class=\"kw-clinique\">Amaigrissement</span> ; <span class=\"kw-clinique\">déshydratation</span> ; <span class=\"kw-clinique\">douleurs abdominales</span> ; <br>\n              <span class=\"kw-alerte\">Hypokaliémie</span> sévère.\n            </td>\n            <td>\n              <span class=\"kw-bio\">VIP</span> élevé.\n            </td>\n            <td><span class=\"kw-chiffre\">80 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Glucagonome</span></th>\n            <td><span class=\"kw-chiffre\">4 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Érythème nécrolytique migrateur</span> aux points de friction (dermatose bulleuse) ; <br>\n              <span class=\"kw-clinique\">Diabète</span> par stimulation de la néoglucogénèse ; <br>\n              <span class=\"kw-clinique\">Amaigrissement</span> (protéolyse + lipolyse) ; <br>\n              <span class=\"kw-clinique\">Anémie</span> ; <span class=\"kw-alerte\">thromboembolies</span> ; <span class=\"kw-clinique\">diarrhée</span> ; alopécie, dép<span class=\"kw-chiffre\">igm</span>entation, conjonctivite.\n            </td>\n            <td>\n              <span class=\"kw-bio\">Glucagon</span> circulant élevé.\n            </td>\n            <td><span class=\"kw-chiffre\">80 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Somatostatinome</span></th>\n            <td><span class=\"kw-chiffre\">&lt; 5 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Diarrhée</span> ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-clinique\">lithiase vésiculaire</span>.\n            </td>\n            <td>\n              Somatostatine élevée.\n            </td>\n            <td><span class=\"kw-chiffre\">50 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">ACTHome</span> <br>(<span class=\"kw-def\">Cushing paranéoplasique</span>)</th>\n            <td><span class=\"kw-chiffre\">&lt; 1 %</span></td>\n            <td>\n              Signes de <span class=\"kw-clinique\">syndrome de Cushing</span> sévères, d'installation rapide.\n            </td>\n            <td>\n              <span class=\"kw-bio\">Cortisol libre urinaire des 24 h</span> élevé + <span class=\"kw-bio\">ACTH</span> circulante inadaptée.\n            </td>\n            <td><span class=\"kw-chiffre\">&gt; 90 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">GRFome</span></th>\n            <td><span class=\"kw-chiffre\">&lt; 1 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Acromégalie</span>.\n            </td>\n            <td>\n              <span class=\"kw-bio\">GHRH</span>, <span class=\"kw-bio\">GH</span>, <span class=\"kw-bio\">IGF-1</span> élevés.\n            </td>\n            <td><span class=\"kw-chiffre\">30 %</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">PTH-like-ome</span></th>\n            <td><span class=\"kw-chiffre\">&lt; 1 %</span></td>\n            <td>\n              <span class=\"kw-clinique\">Hypercalcémie</span> ; <span class=\"kw-clinique\">douleurs osseuses</span> ; parathyroïdes normales.\n            </td>\n            <td>\n              PTHrP élevée.\n            </td>\n            <td><span class=\"kw-chiffre\">&gt; 90 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeaux rouges</span> cliniques à connaître</strong> :\n        <ul>\n          <li><span class=\"kw-clinique\">Angiocholite</span> sur <span class=\"kw-clinique\">ictère</span> obstructif → <span class=\"kw-alerte\">urgence drainage biliaire</span> (cf. <span class=\"kw-bio\">bilirubine</span> &gt;<span class=\"kw-chiffre\"> 250 µmol/L</span>, dénutrition majeure).</li>\n          <li><span class=\"kw-clinique\">Phlébites migratrices récidivantes</span> &gt;<span class=\"kw-chiffre\"> 50 ans</span> → rechercher cancer du pancréas.</li>\n          <li><span class=\"kw-def\">Loi de Courvoisier-Terrier</span> (grosse <span class=\"kw-clinique\">vésicule</span> tendue indolore + <span class=\"kw-clinique\">ictère</span>) → écarte la lithiase, oriente vers obstruction <span class=\"kw-etio\">tumorale</span>.</li>\n          <li><span class=\"kw-clinique\">Ulcères multiples / récidivants</span> sous <span class=\"kw-ttt\">IPP</span> à forte dose → évoquer un <span class=\"kw-def\">gastrinome</span>.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 251 — <span class=\"kw-clinique\">Amaigrissement</span> · 269 — Douleur abdominale aiguë · 277 — Lithiase biliaire</em></p>","frequence":6},{"id":"308-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens de biologie devant une tumeur du pancréas","contenu":"<div class=\"callout callout-info\">\n        <strong>À retenir d'emblée</strong> — <span class=\"kw-ci\">aucun examen biologique n'est diagnostique</span> d'un adénocarcinome du pancréas. <span class=\"kw-clinique\">Les</span> marqueurs ont une valeur <strong>pronostique</strong> (adéno) ou <strong>de <span class=\"kw-def\">suivi</span></strong> (TNE). Le diagnostic repose sur l'<span class=\"kw-imagerie\">imagerie</span> et la <span class=\"kw-bio\">preuve histologique</span> (si non-résécable).\n      </div>\n\n      <h4>1 · Adénocarcinome — <span class=\"kw-bio\">CA 19-9</span> et bilan <span class=\"kw-ttt\">biologique</span></h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-bio\">CA 19-9</span></th>\n            <td>\n              <strong>Pas un outil diagnostique</strong> ❌ — Se <span class=\"kw-chiffre\">80 %</span>, Sp <span class=\"kw-chiffre\">80-90 %</span>, VPP faible ; <br>\n              <strong>Valeur pronostique</strong> : taux pré-thérapeutique corrélé à la <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span> ; <br>\n              <strong>Exception diagnostique</strong> : masse pancréatique sans <span class=\"kw-bio\">histologie</span> obtenue (<span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-ttt\">biopsie</span> négative écho-endoscopique) + <span class=\"kw-bio\">CA 19-9 &gt; 10 N</span> (N &lt; 37 U/mL) <strong>sans <span class=\"kw-clinique\">cholestase</span></strong> → diagnostic d'adénoK retenu ; <br>\n              <strong>Faux négatifs</strong> : <span class=\"kw-chiffre\">3-7 %</span> de la population <span class=\"kw-bio\">Lewis a− b−</span> ne synthétise pas le <span class=\"kw-bio\">CA 19-9</span> ; <br>\n              <strong>Faux positifs</strong> : autres adénoK (voies biliaires, estomac, côlon-rectum, mucineux ovaire), cholestase y compris bénigne, pancréatite, mucoviscidose, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">hémochromatose</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>Bilan hépatique</th>\n            <td>\n              <span class=\"kw-bio\">Bilirubine</span> élevée + <span class=\"kw-bio\">PAL</span> + <span class=\"kw-bio\">GGT</span> = <span class=\"kw-clinique\">cholestase</span> si cancer obstructif de la tête ; <br>\n              <span class=\"kw-bio\">TP abaissé</span> si cholestase prolongée → à corriger avant toute <span class=\"kw-ttt\">biopsie</span> ou geste interventionnel.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">Glycémie</span> / <span class=\"kw-bio\">HbA1c</span></th>\n            <td>\n              <strong>Hyperglycémie</strong> dans <span class=\"kw-chiffre\">15-50 %</span> des cas (<span class=\"kw-etio\">paranéoplasique</span> ou <span class=\"kw-alerte\">décompensation</span> de DT2).\n            </td>\n          </tr>\n          <tr>\n            <th>État nutritionnel</th>\n            <td>\n              <span class=\"kw-bio\">Albuminémie</span> + <span class=\"kw-bio\">préalbumine</span> ; <br>\n              En cas d'<span class=\"kw-alerte\">ictère avec dénutrition</span> → <span class=\"kw-ttt\">drainage</span> biliaire pré-op + renutrition avant chirurgie.\n            </td>\n          </tr>\n          <tr>\n            <th>Bilan pré-imagerie</th>\n            <td>\n              <span class=\"kw-bio\">Créatininémie</span> + <span class=\"kw-bio\">clairance</span> avant <span class=\"kw-imagerie\">TDM</span> injectée.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span></th>\n            <td>\n              <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">NFS</span> — non spécifiques, contribuent au bilan général.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · TNE — biologie spécifique</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-bio\">Chromogranine A (CGA)</span></th>\n            <td>\n              <strong>Seul marqueur <span class=\"kw-ttt\">biologique</span> utile au <span class=\"kw-def\">suivi</span></strong> du traitement des TNE ; <br>\n              Se <span class=\"kw-chiffre\">55-80 %</span>, Sp <span class=\"kw-chiffre\">98 %</span>, N ≈ <span class=\"kw-chiffre\">85 U/L</span> ; <br>\n              <strong>Nombreux faux positifs</strong> ⚠️ : <span class=\"kw-clinique\">hypergastrinémie</span> (la plus fréquente — interprétable seulement si gastrinémie normale), <span class=\"kw-ci\">insuffisance cardiaque</span> ou rénale chronique, stress majeur, <span class=\"kw-etio\">NEM1</span>, <span class=\"kw-clinique\">syndrome de Cushing</span>, <span class=\"kw-ttt\">IPP</span>, analogues de la somatostatine.\n            </td>\n          </tr>\n          <tr>\n            <th>Dosages systématiques</th>\n            <td>\n              <span class=\"kw-bio\">Gastrine</span> — pour interpréter la CGA, ou si suspicion de gastrinome ; <br>\n              <span class=\"kw-bio\">Calcémie ionisée</span> + <span class=\"kw-bio\">PTH</span> — recherche d'hyperparathyroïdie (<span class=\"kw-def\">terrain</span> NEM1).\n            </td>\n          </tr>\n          <tr>\n            <th>Dosages selon symptôme</th>\n            <td>\n              <span class=\"kw-bio\">Proinsuline</span> + <span class=\"kw-bio\">peptide C</span> + insulinémie + <span class=\"kw-bio\">glycémie</span> — hypoglycémie organique (insulinome) ; <br>\n              <span class=\"kw-bio\">VIP</span> — <span class=\"kw-clinique\">diarrhée</span> profuse (VIPome) ; <br>\n              <span class=\"kw-bio\">Glucagon</span> — <span class=\"kw-clinique\">érythème</span> nécrolytique migrateur (glucagonome) ; <br>\n              <span class=\"kw-bio\">5-HIAA urinaires des 24 h</span> — syndrome carcinoïde ; <br>\n              <span class=\"kw-bio\">Cortisol libre urinaire des 24 h</span> + <span class=\"kw-bio\">ACTH</span> — Cushing <span class=\"kw-etio\">paranéoplasique</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>Tumeur peu différenciée</th>\n            <td>\n              <span class=\"kw-bio\">NSE</span> (Neurone Specific Enolase) peut être dosée.\n            </td>\n          </tr>\n          <tr>\n            <th>Bilan anapath (pièce opératoire)</th>\n            <td>\n              <span class=\"kw-bio\">Immunohistochimie</span> : <span class=\"kw-bio\">CGA</span>, <span class=\"kw-bio\">synaptophysine</span>, <span class=\"kw-bio\">NCAM (CD56)</span> — positivité de 2/3 nécessaire ; <br>\n              <span class=\"kw-bio\">Ki-67</span> : grading OMS 2017 — G1 <span class=\"kw-chiffre\">&lt; 3 %</span>, G2 <span class=\"kw-chiffre\">3-20 %</span>, G3 <span class=\"kw-chiffre\">&gt; 20 %</span> ; <br>\n              Au sein du <span class=\"kw-def\">grade</span> G3, distinguer la <span class=\"kw-def\">TNE G3</span> bien différenciée (<span class=\"kw-def\">pronostic</span> intermédiaire) du <span class=\"kw-def\">CNE</span> (<span class=\"kw-clinique\">carcinome</span> neuroendocrine peu différencié, <span class=\"kw-alerte\">pronostic défavorable</span>) ; <br>\n              Forme mixte : <span class=\"kw-def\">MiNEN</span> (<em>Mixed Neuroendocrine-Non-neuroendocrine Neoplasm</em>) si composante neuroendocrine <span class=\"kw-chiffre\">≥ 30 %</span> associée à un adénocarcinome.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM</strong> — un <span class=\"kw-bio\">CA 19-9 élevé</span> chez un patient ictérique <strong>ne signe pas un cancer</strong> : la <span class=\"kw-clinique\">cholestase</span> est elle-même responsable d'élévations marquées. Toujours redoser après résolution de l'hyperbilirubinémie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — Anapath</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/pancreatic-neoplasms","label":"Radiopaedia : Pancreatic neoplasms"},{"href":"https://radiopaedia.org/articles/pancreatic-ductal-adenocarcinoma-4?lang=us","label":"Radiopaedia : Pancreatic ductal adenocarcinoma 4"},{"href":"https://radiopaedia.org/articles/pancreas","label":"Radiopaedia : Pancreas"},{"href":"https://radiopaedia.org/articles/cystic-lesions-of-the-pancreas-differential","label":"Radiopaedia : Cystic lesions of the pancreas differential"},{"href":"https://radiopaedia.org/articles/serous-cystadenoma-of-the-pancreas-1?lang=us","label":"Radiopaedia : Serous cystadenoma of the pancreas 1"},{"href":"https://radiopaedia.org/articles/mucinous-cystadenoma-of-the-pancreas-1","label":"Radiopaedia : Mucinous cystadenoma of the pancreas 1"},{"href":"https://radiopaedia.org/articles/intraductal-papillary-mucinous-neoplasm","label":"Radiopaedia : Intraductal papillary mucinous neoplasm"},{"href":"https://radiopaedia.org/articles/insulinoma","label":"Radiopaedia : Insulinoma"},{"href":"https://radiopaedia.org/articles/pancreatic-neuroendocrine-tumours-2?lang=us","label":"Radiopaedia : Pancreatic neuroendocrine tumours 2"}]},{"id":"308-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie d’une tumeur du pancréas","contenu":"<h4>1 · Adénocarcinome — stratégie d'imagerie</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications et rendement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">Échographie abdominale</span></th>\n            <td>\n              1ʳᵉ intention en débrouillage (<span class=\"kw-clinique\">ictère</span>, douleur abdominale) ; <br>\n              <strong>Tumeur</strong> : <span class=\"kw-imagerie\">hypoéchogène</span>, contours flous ; <br>\n              <strong>Signes indirects</strong> : <span class=\"kw-imagerie\">dilatation des voies biliaires</span> intra/extra-hépatiques ; <span class=\"kw-imagerie\">grosse vésicule</span> (<span class=\"kw-chiffre\">50 %</span>) ; <span class=\"kw-imagerie\">dilatation du Wirsung &gt; 2 mm</span> ; <span class=\"kw-clinique\">adénopathies</span> ; <span class=\"kw-clinique\">ascite</span> ; métastases hépatiques ; <span class=\"kw-alerte\">thrombose portale</span> ; <br>\n              <strong>Limites</strong> ⚠️ : Se <span class=\"kw-chiffre\">55-90 %</span>, tumeurs &lt;<span class=\"kw-chiffre\"> 2 cm</span>, tumeurs de la queue, atteinte diffuse ; <br>\n              <strong>Normalité n'exclut pas le diagnostic ❌</strong> — opérateur-dépendant, non recommandée isolément.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">TDM-TAP injectée protocole pancréas</span></th>\n            <td>\n              <span class=\"kw-alerte\">Examen de référence</span> — 1ʳᵉ intention si tumeur fortement suspectée (<span class=\"kw-clinique\">ictère</span> nu + <span class=\"kw-clinique\">AEG</span>) ; <br>\n              <strong>Tumeur</strong> : <span class=\"kw-clinique\">lésion</span> <span class=\"kw-imagerie\">hypodense</span> mal limitée (<span class=\"kw-chiffre\">80-95 %</span>) à la phase parenchymateuse (fibreuse) ; <br>\n              <strong>Signes indirects</strong> : dilatation VBP et Wirsung ; <span class=\"kw-imagerie\">atrophie parenchymateuse d'amont</span> ⭐ ; pseudo-kyste d'amont (<span class=\"kw-chiffre\">8-10 %</span>) ; <br>\n              <strong><span class=\"kw-def\">Bilan d'extension</span></strong> : disparition de l'espace graisseux sur <span class=\"kw-chiffre\">&gt; 180°</span> de l'<span class=\"kw-imagerie\">AMS</span> = non-résécabilité ; <span class=\"kw-bio\">envahissement</span> <span class=\"kw-imagerie\">VMS / veine porte</span> ; <span class=\"kw-clinique\">HTP</span> (<span class=\"kw-ci\">contre-indication</span> chirurgicale) ; métastases hépatiques, péritonéales, pulmonaires.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">IRM pancréatique</span></th>\n            <td>\n              <strong>Visée diagnostique</strong> : tumeur en <span class=\"kw-imagerie\">hypoT1 fat-sat</span> ; alternative si <span class=\"kw-ci\">intolérance à l'iode</span>, <span class=\"kw-clinique\">lésion</span> non vue en <span class=\"kw-imagerie\">TDM</span>, ou tumeurs kystiques ; <br>\n              <strong><span class=\"kw-def\">Bilan d'extension</span></strong> : recommandée avant <span class=\"kw-ttt\">chirurgie</span> pour éliminer des métastases hépatiques occultes.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">Écho-endoscopie</span></th>\n            <td>\n              Se <span class=\"kw-chiffre\">72 %</span>, Sp <span class=\"kw-chiffre\">90 %</span> ; opérateur-dépendant, sous sédation ; <br>\n              <strong>Visée diagnostique</strong> : <span class=\"kw-alerte\">meilleur examen pour tumeurs &lt; 2 cm</span> ; preuve cytologique / histologique par cytoponction si tumeur <strong>non résécable</strong> ; <br>\n              <strong><span class=\"kw-def\">Bilan d'extension</span> locorégional</strong> : <span class=\"kw-bio\">envahissement</span> ganglionnaire ; précise l'envahissement vasculaire si <span class=\"kw-imagerie\">scanner</span> douteux ; <br>\n              <span class=\"kw-ci\">Impossible</span> si sténose digestive infranchissable ou ATCD de gastrectomie partielle ⚠️.\n            </td>\n          </tr>\n          <tr>\n            <th>Place de la <span class=\"kw-ttt\">biopsie</span></th>\n            <td>\n              <strong>Indications</strong> : tumeur <span class=\"kw-alerte\">non-résécable</span> ou <span class=\"kw-alerte\">métastatique</span> ; <br>\n              Voies : percutanée (écho/<span class=\"kw-imagerie\">TDM</span>-guidée) tumeur ; sous cœlioscopie sur métastases péritonéales ; <span class=\"kw-ttt\">ponction</span>-biopsie sur métastase hépatique ou <span class=\"kw-clinique\">adénopathie</span> sus-claviculaire ; <br>\n              <span class=\"kw-ci\">Ne pas ponctionner une tumeur résécable chez un patient opérable ❌</span>.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">TEP-FDG</span></th>\n            <td>\n              <span class=\"kw-ci\">Pas d'intérêt dans le cancer du pancréas ❌</span> — ne différencie pas <span class=\"kw-clinique\">pancréatite chronique</span> et cancer.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">CPRE</span> / <span class=\"kw-imagerie\">TDM</span> thoracique</th>\n            <td>\n              <span class=\"kw-ci\">CPRE</span> ❌ : pas de place diagnostique, à envisager seulement pour pose de prothèse de <span class=\"kw-ttt\">drainage</span> ; <br>\n              <span class=\"kw-imagerie\">TDM</span> thoracique non coût-efficace isolé (métastases pulmonaires isolées exceptionnelles), mais <span class=\"kw-imagerie\">TDM</span>-TAP en pratique systématique.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · TNE — imagerie morphologique et fonctionnelle</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">TDM-TAP injectée</span></th>\n            <td>\n              <strong>Examen de référence</strong> ; <br>\n              <span class=\"kw-imagerie\">Hypervascularisation au temps artériel précoce</span> ++ et temps portal ; <br>\n              Tumeur bien délimitée sans capsule ; absence de dilatation canalaire ; <br>\n              Multiplicité possible (<span class=\"kw-chiffre\">60 %</span> des gastrinomes, &lt;<span class=\"kw-chiffre\"> 10 %</span> des insulinomes).\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">IRM</span></th>\n            <td>\n              Tumeur en <span class=\"kw-imagerie\">hypoT1, hyperT2</span>, réhaussement par gadolinium ; <br>\n              <strong><span class=\"kw-imagerie\">IRM</span> hépatique</strong> plus sensible que la <span class=\"kw-imagerie\">TDM</span> pour métastases hépatiques ; <br>\n              <strong><span class=\"kw-imagerie\">IRM</span> rachis (au minimum)</strong> ou corps entier — métastases osseuses.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">Écho-endoscopie</span></th>\n            <td>\n              Examen le plus sensible pour <span class=\"kw-clinique\">les</span> petites tumeurs : <span class=\"kw-def\">insulinomes</span>, <span class=\"kw-def\">gastrinomes</span> ; <br>\n              Permet <span class=\"kw-ttt\">ponction</span>-biopsie ; <br>\n              <strong>Systématique en cas de gastrinome</strong> pour explorer paroi duodénale + tête du pancréas.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">Gastroscopie</span></th>\n            <td>\n              Avec <strong>biopsies fundiques</strong> — en cas de suspicion de <span class=\"kw-def\">gastrinome</span>.\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">TEP DOTATOC Gallium</span></th>\n            <td>\n              <strong>Référence</strong> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">TNE pancréatiques bien différenciées</span> — <span class=\"kw-imagerie\">TEP</span> des récepteurs de la somatostatine ; <br>\n              Alternative : <span class=\"kw-imagerie\">OctréoScan</span> (<span class=\"kw-imagerie\">scintigraphie</span> au pentétréotide marqué à l'indium 111).\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">TEP-FDG</span></th>\n            <td>\n              <span class=\"kw-ci\">Pas d'intérêt</span> dans <span class=\"kw-clinique\">les</span> TNE bien différenciées ❌ ; <br>\n              <strong>Indiqué</strong> pour les carcinomes neuroendocrines peu différenciés de haut <span class=\"kw-def\">grade</span> (CNE) ou <span class=\"kw-bio\">Ki-67 &gt; 10 %</span> ; <br>\n              <strong>Valeur pronostique</strong> : DOTATOC+ / FDG− = bon <span class=\"kw-def\">pronostic</span> ; OctréoScan− / FDG+ = mauvais pronostic.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Tumeurs kystiques — démarche diagnostique</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">TDM-TAP + IRM pancréatique</span></th>\n            <td>1ʳᵉ intention systématique pour caractérisation morphologique.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">Écho-endoscopie + ponction</span></th>\n            <td>\n              <strong>Indispensable</strong>, sauf si <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> concluent formellement à un cystadénome séreux typique ou à un cancer ; <br>\n              Analyse biochimique du liquide : <span class=\"kw-bio\">ACE bas</span> = cystadénome séreux ; <span class=\"kw-bio\">ACE &gt; 300 ng/mL</span> ou <span class=\"kw-bio\">CA 19-9 &gt; 50 000 U/mL</span> = mucineux ; <br>\n              Analyse cytologique.\n            </td>\n          </tr>\n          <tr>\n            <th>Sémiologie radiologique caractéristique</th>\n            <td>\n              <span class=\"kw-def\">Cystadénome séreux</span> : kystes &lt;<span class=\"kw-chiffre\"> 2 mm</span>, <span class=\"kw-imagerie\">aspect en nid d'abeille</span>, cicatrice centrale calcifiée ; pas de communication canalaire ; <br>\n              <span class=\"kw-def\">Cystadénome mucineux</span> :<span class=\"kw-chiffre\"> 10-30 mm</span>, uni/oligo-kystique, <span class=\"kw-imagerie\">hypersignal T1</span> discret, septas possibles, pas de communication canalaire ; <br>\n              <span class=\"kw-def\">TIPMP du canal principal</span> : <span class=\"kw-imagerie\">Wirsung &gt; 3 mm</span>, <span class=\"kw-alerte\">pathognomonique si &gt; 15 mm</span> sans sténose ; <br>\n              <span class=\"kw-def\">TIPMP des canaux secondaires</span> : <span class=\"kw-imagerie\">aspect en grappe de raisin</span>, communication avec Wirsung (<span class=\"kw-imagerie\">IRM</span> = référence).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Synthèse stratégique</strong> — devant toute suspicion de tumeur du pancréas, l'examen pivot est la <span class=\"kw-imagerie\">TDM-TAP injectée protocole pancréas</span>. L'imagerie fonctionnelle (<span class=\"kw-imagerie\">TEP DOTATOC</span>) est réservée aux TNE bien différenciées. Le <span class=\"kw-imagerie\">TEP-FDG</span> n'a <strong>aucune place</strong> dans le bilan de l'adénocarcinome.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 304 — Tumeur du foie</em></p>","frequence":3},{"id":"308-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie descriptive d’une tumeur kystique du pancréas","contenu":"<h4><span class=\"kw-def\">Épidémiologie</span> générale des lésions kystiques pancréatiques</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévalence</span></strong> en population générale : <span class=\"kw-chiffre\">2,4 %</span>, augmente avec l'âge — <span class=\"kw-chiffre\">10 %</span> après <span class=\"kw-chiffre\">70 ans</span>.</li>\n        <li><strong>Découverte fortuite</strong> ++ : de plus en plus fréquente avec l'usage courant de l'imagerie en coupes.</li>\n        <li>Découverte symptomatique (rare) : <span class=\"kw-clinique\">douleur solaire</span>, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">pancréatite aiguë</span>, <span class=\"kw-clinique\">hémorragie digestive</span>.</li>\n        <li><span class=\"kw-def\">Pseudo-kystes</span> = <span class=\"kw-chiffre\">90 %</span> des lésions kystiques (séquelles de <span class=\"kw-clinique\">pancréatite aiguë</span> ou chronique) — <span class=\"kw-ci\">ne dégénèrent jamais ❌</span>.</li>\n        <li><span class=\"kw-def\">Tumeurs kystiques vraies</span> = <span class=\"kw-chiffre\">10 %</span> restants, soit <span class=\"kw-chiffre\">5 %</span> de l'ensemble des tumeurs du pancréas.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Mnémotechnique pivot</strong> — <em>Séreux comme <strong>sympa</strong></em>, <em>Mucineux comme <strong>méchant / malin</strong></em>. L'évaluation du <strong>risque de cancérisation</strong> est l'enjeu principal de la stratégie diagnostique d'une <span class=\"kw-clinique\">lésion</span> kystique pancréatique.\n      </div>\n\n      <h4>Évaluation du risque de dégénérescence</h4>\n      <table >\n        <thead>\n          <tr><th>Risque</th><th>Lésions concernées</th><th>Implications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Sans risque ou négligeable</th>\n            <td>\n              <span class=\"kw-def\">Pseudo-kyste</span> (<span class=\"kw-chiffre\">90 %</span>) ; <br>\n              <span class=\"kw-def\">Cystadénome séreux</span> ; <br>\n              Kystes congénitaux ; kystes rétentionnels.\n            </td>\n            <td>\n              <span class=\"kw-def\">Surveillance</span> allégée — pour le cystadénome séreux, <span class=\"kw-chiffre\">1 seul examen</span> de confirmation à<span class=\"kw-chiffre\"> 6-12 mois</span> ; <br>\n              <span class=\"kw-ci\">Ponction inutile ❌</span> pour le cystadénome séreux.\n            </td>\n          </tr>\n          <tr>\n            <th>Faible</th>\n            <td>\n              <span class=\"kw-def\">TIPMP des canaux secondaires</span> ; <br>\n              Tumeur endocrine kystique.\n            </td>\n            <td>\n              Risque de dégénérescence à<span class=\"kw-chiffre\"> 5 ans</span> <span class=\"kw-chiffre\">5-15 %</span> pour TIPMP secondaires ; <br>\n              <span class=\"kw-def\">Surveillance</span> imagerie rapprochée selon <span class=\"kw-alerte\">signes d'alarme</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>Élevé 🔥</th>\n            <td>\n              Lésions sécrétant de la <strong>mucine</strong> : <br>\n              <span class=\"kw-def\">Cystadénome mucineux</span> ; <br>\n              <span class=\"kw-def\">TIPMP du canal principal</span>.\n            </td>\n            <td>\n              <span class=\"kw-alerte\">État précancéreux</span> ; <br>\n              <strong><span class=\"kw-ttt\">Chirurgie</span> d'exérèse réglée systématique</strong> pour le cystadénome mucineux ; <br>\n              Risque de dégénérescence à<span class=\"kw-chiffre\"> 5 ans</span> <span class=\"kw-chiffre\">50 %</span> pour TIPMP canal principal → indication opératoire formelle.\n            </td>\n          </tr>\n          <tr>\n            <th>Dégénéré</th>\n            <td>\n              <span class=\"kw-alerte\">Cystadénocarcinome</span> (mucineux) ; <br>\n              TIPMP dégénérée (<span class=\"kw-clinique\">carcinome</span> <em>in situ</em> ou invasif).\n            </td>\n            <td>\n              Prise en charge oncologique.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Profils épidémiologiques des principales tumeurs kystiques</h4>\n      <table >\n        <thead>\n          <tr><th>Tumeur</th><th><span class=\"kw-def\">Terrain</span></th><th>Localisation</th><th>Imagerie clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Cystadénome séreux</span></th>\n            <td>Femme &gt;<span class=\"kw-chiffre\"> 50 ans</span> dans <span class=\"kw-chiffre\">75 %</span> des cas.</td>\n            <td>Tête du pancréas, unique.</td>\n            <td><span class=\"kw-imagerie\">Nid d'abeille</span>, kystes &lt;<span class=\"kw-chiffre\"> 2 mm</span>, cicatrice centrale.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Cystadénome mucineux</span></th>\n            <td>Femme <span class=\"kw-chiffre\">50-60 ans</span> dans <span class=\"kw-chiffre\">90 %</span> des cas.</td>\n            <td>Corps ou queue, unique,<span class=\"kw-chiffre\"> 10-30 mm</span>.</td>\n            <td>Uni/oligo-kystique, <span class=\"kw-imagerie\">hypersignal T1</span> discret.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">TIPMP</span></th>\n            <td>~<span class=\"kw-chiffre\">65 ans</span>, 2 sexes, <span class=\"kw-chiffre\">2 %</span> des adultes, &gt; <span class=\"kw-chiffre\">10 %</span> des <span class=\"kw-chiffre\">≥ 70 ans</span>.</td>\n            <td>Diffuse, atteinte canalaire (principal ± secondaires).</td>\n            <td><span class=\"kw-imagerie\">Wirsung &gt; 3 mm</span> (pathognomonique &gt;<span class=\"kw-chiffre\"> 15 mm</span>) ; aspect en grappe de raisin.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Tumeur de Frantz</span> <br>(pseudo-papillaire et solide)</th>\n            <td>Enfant ou femme &lt;<span class=\"kw-chiffre\"> 40 ans</span>.</td>\n            <td>Variable, parfois volumineuse.</td>\n            <td>Contenu inhomogène, souvent solide et <span class=\"kw-etio\">hémorragique</span> ; risque de dégénérescence <span class=\"kw-chiffre\">10-20 %</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://chirurgie-digestive-sat.aphp.fr/chirurgie/pancreatectomies/anatomie-du-pancreas/","label":"Anatomie du pancreas"},{"href":"https://www.sfendocrino.org/item-308-tumeurs-neuroendocrines-du-pancreas/","label":"SFE — Item 308 tumeurs neuroendocrines du pancreas"}],"cards":[{"i":"3814af43a46a","n":308,"o":"308-1","u":"Définition","t":"Connaître les deux principaux types histologiques des tumeurs du pancréas","q":"Quels sont les deux principaux types histologiques de tumeurs du pancréas que l'on doit connaître pour l'EDN, et quelle est leur fréquence relative ?","a":"<p>Les deux principaux types histologiques de tumeurs du pancréas sont :</p><ul><li>L'<strong>adénocarcinome canalaire (ductal) du pancréas exocrine</strong> : il représente <strong>95%</strong> des cancers du pancréas, dont 90% sont des adénocarcinomes canalaires purs.</li><li>Les <strong>tumeurs neuroendocrines malignes (TNE)</strong> : elles représentent <strong>2 à 4%</strong> des cancers du pancréas.</li></ul>"},{"i":"4fa279554b85","n":308,"o":"308-1","u":"Définition","t":"Connaître les deux principaux types histologiques des tumeurs du pancréas","q":"Quelle est la caractéristique principale de l'adénocarcinome canalaire du pancréas en termes de prévalence ?","a":"<p>L'adénocarcinome canalaire du pancréas exocrine est, de loin, le type le plus fréquent, représentant <strong>95%</strong> de tous les cancers du pancréas. Au sein de ce groupe, 90% sont des adénocarcinomes canalaires purs.</p>"},{"i":"7fe5e0f5f279","n":308,"o":"308-1","u":"Définition","t":"Connaître les deux principaux types histologiques des tumeurs du pancréas","q":"Comment les tumeurs neuroendocrines (TNE) malignes du pancréas peuvent-elles se présenter en termes de sécrétion hormonale ?","a":"<p>Les tumeurs neuroendocrines malignes du pancréas peuvent être :</p><ul><li><strong>Non sécrétantes</strong> (cas le plus fréquent).</li><li><strong>Sécrétantes</strong>, produisant diverses hormones comme l'<strong>insuline</strong>, la <strong>gastrine</strong>, le <strong>VIP</strong> (peptide intestinal vasoactif), le <strong>glucagon</strong> ou la <strong>somatostatine</strong>.</li></ul>"},{"i":"05610d56b45d","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Quelle est la présentation clinique caractéristique du gastrinome pancréatique ?","a":"<p>Le gastrinome (syndrome de Zollinger-Ellison) est caractérisé par :</p><ul><li>Une <strong>maladie ulcéreuse sévère</strong> avec ulcères multiples ou récidivants, souvent compliqués (hémorragie, perforation), et fréquemment associés à une œsophagite peptique sévère.</li><li>Une <strong>diarrhée chronique volumogénique sécrétoire</strong> avec malabsorption, qui s'améliore ou disparaît sous IPP.</li></ul>"},{"i":"7febc8eb6406","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Décrivez les signes cliniques majeurs d'un glucagonome pancréatique.","a":"<p>Le glucagonome se présente cliniquement par :</p><ul><li>Un <strong>érythème nécrolytique migrateur</strong>, une dermatose bulleuse caractéristique aux points de friction.</li><li>Un diabète sucré dû à la stimulation de la néoglucogenèse.</li><li>Un amaigrissement (par protéolyse et lipolyse).</li><li>Des anémies, des événements thromboemboliques, des diarrhées, une alopécie et une dépigmentation.</li></ul>"},{"i":"ba0aa52efa55","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Comment se présentent cliniquement les Tumeurs NeuroEndocrines (TNE) pancréatiques non fonctionnelles ?","a":"<p>Les TNE pancréatiques non fonctionnelles (<strong>75-80%</strong> des cas) se caractérisent souvent par des symptômes peu spécifiques :</p><ul><li>Amaigrissement.</li><li>Douleur abdominale.</li><li>Ictère.</li><li>Elles sont souvent découvertes fortuitement lors d'un examen d'imagerie (incidentalome) ou dans le cadre du bilan d'une prédisposition génétique (ex: NEM1, VHL).</li></ul>"},{"i":"c9327ae577c0","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Quels sont les principaux signes cliniques d'un insulinome pancréatique ?","a":"<p>L'insulinome se manifeste par une triade de signes liés à l'hypoglycémie organique :</p><ul><li>Crises d'hypoglycémie, survenant à jeun ou à l'effort.</li><li>Symptômes adrénergiques : <strong>sueurs</strong>, <strong>tremblements</strong>, tachycardie.</li><li>Signes neuroglucopéniques : désorientation, crises comitiales, <strong>coma</strong>.</li><li>Une prise de poids est observée dans <strong>30%</strong> des cas.</li></ul>"},{"i":"d669faf0f085","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Quels sont les signes cliniques les plus fréquents de l'adénocarcinome de la tête du pancréas ?","a":"<p>L'adénocarcinome de la tête du pancréas se manifeste fréquemment par :</p><ul><li>Un ictère nu cholestatique, lentement progressif, sans fièvre ni colique hépatique, avec urines foncées, selles décolorées et prurit.</li><li>Une grosse vésicule palpable, tendue et indolore (loi de Courvoisier-Terrier), retrouvée dans <strong>50%</strong> des cas.</li><li>Une douleur, présente dans <strong>70-75%</strong> des cas, souvent transfixiante, insomniante, et favorisée par le décubitus dorsal, surtout si la tumeur atteint le corps du pancréas.</li><li>Un syndrome d'altération de l'état général (AEG) avec anorexie, fatigue et amaigrissement rapide et important.</li></ul>"},{"i":"f47d0eb09d25","n":308,"o":"308-3","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques de l’adénocarcinome du pancréas et des tumeurs neuroendocrines","q":"Citez les signes paranéoplasiques majeurs pouvant orienter vers un adénocarcinome du pancréas.","a":"<p>Les signes paranéoplasiques importants incluent :</p><ul><li>La décompensation d'un diabète connu ou la survenue d'un diabète récent chez un sujet de <strong>plus de 50 ans</strong> sans facteurs de risque.</li><li>Des phlébites migratrices et récidivantes, associées à des embolies pulmonaires.</li><li>Un syndrome dépressif ou une anxiété nouvelle et persistante.</li></ul>"},{"i":"15334b11be65","n":308,"o":"308-4","u":"Examens complémentaires","t":"Connaître les indications des examens de biologie devant une tumeur du pancréas","q":"Quels bilans biologiques sont indiqués de manière générale en cas de suspicion de tumeur du pancréas pour le bilan hépatique, métabolique et nutritionnel pré-thérapeutique ?","a":"<ul><li><strong>Bilan hépatique :</strong> Dose de la <strong>bilirubine</strong>, les <strong>PAL</strong> et les <strong>GGT</strong> pour évaluer une cholestase en cas de cancer obstructif de la tête du pancréas. Le <strong>TP</strong> (taux de prothrombine) est à évaluer car il peut être abaissé en cas de cholestase prolongée et doit être corrigé avant toute procédure invasive.</li><li><strong>Bilan métabolique :</strong> La <strong>glycémie</strong> et l'<strong>HbA1c</strong> sont recommandées car une hyperglycémie est présente dans 15-50% des cas (paranéoplasique ou décompensation de DT2).</li><li><strong>État nutritionnel :</strong> L'<strong>albuminémie</strong> et la <strong>préalbumine</strong> sont dosées. En cas d'ictère avec dénutrition, un <strong>drainage biliaire pré-opératoire et une renutrition</strong> sont nécessaires avant la chirurgie.</li></ul>"},{"i":"236b6f80fc30","n":308,"o":"308-4","u":"Examens complémentaires","t":"Connaître les indications des examens de biologie devant une tumeur du pancréas","q":"Quelle est la valeur diagnostique du marqueur CA 19-9 dans le contexte d'un adénocarcinome du pancréas ?","a":"<p>Le <strong>CA 19-9 n'est pas un outil diagnostique</strong> de première intention pour l'adénocarcinome du pancréas. Sa sensibilité et spécificité sont d'environ <strong>80-90%</strong>, mais sa <strong>VPP est faible</strong>.</p><p>Une exception diagnostique est admise en cas de masse pancréatique sans histologie obtenue (après ≥ 1 biopsie négative par écho-endoscopie) avec un <strong>CA 19-9 &gt; 10 N</strong> (N &lt; 37 U/mL) et en <strong>absence de cholestase</strong>, où un diagnostic d'adénocarcinome peut être retenu.</p>"},{"i":"3c01f399b393","n":308,"o":"308-4","u":"Examens complémentaires","t":"Connaître les indications des examens de biologie devant une tumeur du pancréas","q":"Quels dosages biologiques spécifiques sont réalisés selon le tableau clinique pour explorer une TNE pancréatique (insulinome, VIPome, glucagonome, gastrinome, etc.) ?","a":"<ul><li><strong>Insulinome :</strong> Proinsuline, peptide C, insulinémie et glycémie en cas d'hypoglycémie organique.</li><li><strong>VIPome :</strong> VIP en cas de diarrhée profuse.</li><li><strong>Glucagonome :</strong> Glucagon en cas d'érythème nécrolytique migrateur.</li><li><strong>Syndrome carcinoïde :</strong> 5-HIAA urinaires des 24 heures.</li><li><strong>Cushing paranéoplasique :</strong> Cortisol libre urinaire des 24 heures et ACTH.</li><li><strong>Gastrinome :</strong> Gastrinémie est dosée non seulement pour interpréter la CGA, mais aussi si un gastrinome est suspecté.</li></ul>"},{"i":"a9c470d93dc1","n":308,"o":"308-4","u":"Examens complémentaires","t":"Connaître les indications des examens de biologie devant une tumeur du pancréas","q":"Quels sont les marqueurs biologiques spécifiques utilisés pour le suivi des Tumeurs NeuroEndocrines (TNE) pancréatiques et quelles sont leurs limites d'interprétation ?","a":"<p>La <strong>Chromogranine A (CGA)</strong> est le seul marqueur biologique utile au suivi du traitement des TNE. Sa sensibilité est de 55-80% et sa spécificité de 98% (N ≈ 85 U/L).</p><p>Il existe de nombreux <strong>faux positifs</strong> qui rendent son interprétation délicate :</p><ul><li><strong>Hypergastrinémie</strong> (la plus fréquente, la CGA n'est interprétable que si la gastrinémie est normale).</li><li>Insuffisance cardiaque ou rénale chronique.</li><li>Stress majeur.</li><li>NEM1, syndrome de Cushing.</li><li>Prise d'IPP (inhibiteurs de la pompe à protons) et d'analogues de la somatostatine.</li></ul>"},{"i":"b1f3140e3165","n":308,"o":"308-4","u":"Examens complémentaires","t":"Connaître les indications des examens de biologie devant une tumeur du pancréas","q":"Dans quelles situations peut-on observer des faux négatifs ou des faux positifs du CA 19-9 lors de la suspicion d'un adénocarcinome du pancréas ?","a":"<p>Des <strong>faux négatifs</strong> du CA 19-9 sont possibles chez <strong>3-7% de la population Lewis a- b-</strong> qui ne synthétisent pas ce marqueur.</p><p>Des <strong>faux positifs</strong> peuvent être rencontrés dans les situations suivantes :</p><ul><li>Autres adénocarcinomes (voies biliaires, estomac, côlon-rectum, ovaire mucineux).</li><li><strong>Cholestase</strong> (y compris bénigne).</li><li>Pancréatite.</li><li>Mucoviscidose, diabète, hémochromatose.</li></ul>"}]};